import * as React from "react";
import styles from "./ScorecardCommentView.module.scss";

import { CommentsData } from "../services/IScorecardService";

interface ScorecardCommentViewProps {
  level1: CommentsData[];
  level2: CommentsData[];
  onClose: () => void;
}

const ScorecardCommentView = ({ level1, level2, onClose }: ScorecardCommentViewProps) => {
  const allComments = [...level1, ...level2];

  return (
    <div className={styles.commentWrapper}>
      <div className={styles.header}>
        <h3>Justification History</h3>
      </div>
      <div className={styles.list}>
        {allComments.length > 0 ? (
          allComments.map((c, i) => (
            <div key={i} className={styles.commentCard}>
              <div className={styles.row}>
                <span className={styles.role}>{c.RoleName}</span>
                <span className={styles.date}>{c.Date ? new Date(c.Date).toLocaleString() : ""}</span>
              </div>
              <p className={styles.text}>{c.comments}</p>
            </div>
          ))
        ) : (
          <p className={styles.empty}>No justifications found.</p>
        )}
      </div>
    </div>
  );
};

export default ScorecardCommentView;